import{spawn}from'node:child_process';import{mkdir,writeFile}from'node:fs/promises';import{resolve,basename}from'node:path';
const root=resolve('output/cadastros-compras-velocidade-20261118/regressao');await mkdir(root,{recursive:true});
const scripts=['supabase/tests/validate-contas-mensais-catalogo.mjs','supabase/tests/validate-ficha-funcionario.mjs','supabase/tests/validate-suprimentos.mjs','supabase/tests/validate-localizacao-etiquetas.mjs','scripts/verificar-recebimento-pedido.mjs','scripts/verificar-contas-mensais-servicos.mjs','scripts/verificar-simplicidade.mjs','scripts/testar-localizacao-etiquetas.mjs'];
const resultados=[];
for(const script of scripts){const nome=basename(script,'.mjs'),out=resolve(root,nome),inicio=Date.now();await mkdir(out,{recursive:true});const env={...process.env,DB_VALIDATION_RUNTIME:resolve('node_modules/@electric-sql/pglite/dist/index.js'),DB_VALIDATION_MIGRATION_LIMIT:'99999999999999',QA_OUTPUT:out,PLAYWRIGHT_BROWSER:'C:/Program Files/Google/Chrome/Application/chrome.exe'};let log='';const code=await new Promise(ok=>{const p=spawn(process.execPath,[script],{env,windowsHide:true});p.stdout.on('data',b=>log+=b);p.stderr.on('data',b=>log+=b);p.on('close',ok)});await writeFile(resolve(out,'execucao.log'),log);resultados.push({script,code,segundos:(Date.now()-inicio)/1000});await writeFile(resolve(root,'resultados.json'),JSON.stringify(resultados,null,2));console.log(code===0?'PASS':'FAIL',nome,((Date.now()-inicio)/1000).toFixed(1)+'s')}
if(resultados.some(x=>x.code!==0))process.exitCode=1;
